import{_ as a,o as i,c as o,a6 as n}from"./chunks/framework.DNkVJs23.js";const f=JSON.parse('{"title":"Domande frequenti","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/it/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/it/faq/"}],["meta",{"property":"og:title","content":"Domande frequenti | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Dati di Monster Hunter e ricerca di set per Wilds, Rise con Sunbreak e World con Iceborne."}]]},"headers":[],"relativePath":"it/faq/index.md","filePath":"it/faq/index.md"}'),r={name:"it/faq/index.md"};function t(s,e,l,p,c,d){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="domande-frequenti" tabindex="-1">Domande frequenti <a class="header-anchor" href="#domande-frequenti" aria-label="Permalink to &quot;Domande frequenti&quot;">​</a></h1><h2 id="quali-giochi-sono-supportati" tabindex="-1">Quali giochi sono supportati? <a class="header-anchor" href="#quali-giochi-sono-supportati" aria-label="Permalink to &quot;Quali giochi sono supportati?&quot;">​</a></h2><p>Sono supportati Wilds, Rise con Sunbreak e World con Iceborne. Dati e meccaniche restano separati per gioco; il gioco si sceglie dalla schermata iniziale.</p><h2 id="dove-posso-scaricare-l-app" tabindex="-1">Dove posso scaricare l’app? <a class="header-anchor" href="#dove-posso-scaricare-l-app" aria-label="Permalink to &quot;Dove posso scaricare l’app?&quot;">​</a></h2><p>Android è disponibile su <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a> e HarmonyOS su <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a>. La versione iOS è in preparazione. Consulta la sezione <a href="./../#download">download</a>; la disponibilità varia per regione e dispositivo.</p><h2 id="funziona-offline" tabindex="-1">Funziona offline? <a class="header-anchor" href="#funziona-offline" aria-label="Permalink to &quot;Funziona offline?&quot;">​</a></h2><p>I dati sono inclusi nell’app. Consultazione, ricerca, preferiti e ricerca di set funzionano localmente. Link esterni e aggiornamenti richiedono una connessione.</p><h2 id="come-funziona-la-ricerca-di-set" tabindex="-1">Come funziona la ricerca di set? <a class="header-anchor" href="#come-funziona-la-ricerca-di-set" aria-label="Permalink to &quot;Come funziona la ricerca di set?&quot;">​</a></h2><p>Imposta abilità e livelli, fissa o escludi equipaggiamenti e limita le decorazioni a quelle possedute. Rise supporta anche talismani e armature potenziate posseduti. I risultati dipendono dai dati e dai criteri scelti; non è un calcolatore di danni.</p><h2 id="quali-lingue-sono-disponibili" tabindex="-1">Quali lingue sono disponibili? <a class="header-anchor" href="#quali-lingue-sono-disponibili" aria-label="Permalink to &quot;Quali lingue sono disponibili?&quot;">​</a></h2><p>L’app offre 14 lingue. Alcuni testi di gioco possono restare in inglese. Se manca un testo in spagnolo latinoamericano, viene cercato prima in spagnolo di Spagna e poi in inglese.</p><p>English · 日本語 · 简体中文 · 繁體中文 · Français · Deutsch · Italiano · 한국어 · Español (España) · Español (Latinoamérica) · Português (Brasil) · Polski · Русский · العربية</p><h2 id="e-un-app-ufficiale" tabindex="-1">È un’app ufficiale? <a class="header-anchor" href="#e-un-app-ufficiale" aria-label="Permalink to &quot;È un’app ufficiale?&quot;">​</a></h2><p>No. È un’app indipendente di appassionati, non affiliata né approvata da CAPCOM. Le immagini e i dati di Monster Hunter appartengono a CAPCOM Co., Ltd.</p>',14)])])}const h=a(r,[["render",t]]);export{f as __pageData,h as default};
